import{at as e,it as t,t as n,yt as r}from"./chunks/framework.DHfFi6YS.js";var i=JSON.parse(`{"title":"Overview","description":"Start here to opt in to WarpDrive's alpha-stage TypeScript types, then follow the installation, configuration, brands, model typing, and includes typing pages in order.","frontmatter":{"title":"Overview","description":"Start here to opt in to WarpDrive's alpha-stage TypeScript types, then follow the installation, configuration, brands, model typing, and includes typing pages in order."},"headers":[],"relativePath":"guides/the-manual/typescript/index.md","filePath":"guides/the-manual/typescript/index.md"}`),a={name:`guides/the-manual/typescript/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="💚-typescript-guide" tabindex="-1">💚 TypeScript Guide <a class="header-anchor" href="#💚-typescript-guide" aria-label="Permalink to “💚 TypeScript Guide”">​</a></h1><p>Before getting started, we recommend reading the following two sections</p><ul><li><a href="#type-maturity">Notice on Type Maturity</a></li><li><a href="#contributing-type-fixes">Contributing Type Fixes</a></li></ul><hr><ul><li>Installation <ul><li><a href="./installation#using-versions-that-supply-types">Using Versions That Supply Types</a></li><li><a href="./installation#using-types-packages">Using Types Packages</a></li></ul></li><li>Configuration <ul><li><a href="./configuration#using-native-types">Using Native Types</a></li><li><a href="./configuration#using-types-packages">Using Types Packages</a></li></ul></li><li>Usage <ul><li><a href="./why-brands">Why Brands</a></li><li><a href="./typing-models">Typing Models &amp; Transforms</a></li><li><a href="./typing-includes">Typing Includes</a></li><li>Typing Handlers</li><li>Using Store APIs</li></ul></li></ul><hr><h2 id="type-maturity" tabindex="-1">Type Maturity <a class="header-anchor" href="#type-maturity" aria-label="Permalink to “Type Maturity”">​</a></h2><p>We publish types in stages, just like <code>canary | beta | stable</code> channels for code.</p><ul><li><code>private</code> we don&#39;t ship types (yet), even if typed in the repo</li><li><code>alpha</code> we expect high churn on type signatures and users must opt-in to use these types.</li><li><code>beta</code> we expect moderate churn on type signatures and users must opt-in to use these types.</li><li><code>stable</code> we feel the types story is robust enough to attempt to follow semver when changing these types.</li></ul><p>Each package in the project can choose its own stage for types.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>TypeScript support for all EmberData and WarpDrive packages is currently <code>alpha</code>.</p><p><strong>This means that you must opt-in to be able use EmberData&#39;s types.</strong></p></div><h2 id="contributing-type-fixes" tabindex="-1">Contributing Type Fixes <a class="header-anchor" href="#contributing-type-fixes" aria-label="Permalink to “Contributing Type Fixes”">​</a></h2><p>Even though EmberData/WarpDrive is typed, what makes for good types for a project doesn&#39;t necessarily make for good types for that project&#39;s consumers (your application).</p><p>Currently, TypeScript support is <code>alpha</code> largely because we expect to need to improve <strong>a lot</strong> of type signatures to make them more useful and correct for your app.</p><p>Both strategies for installing and consuming types listed in <a href="./installation">installation</a> pull their types from the <code>main</code> branch (canary).</p><p>Every commit to main can be one-click published by us as a new canary version for both installation strategies, this means we can ship type fixes as quickly as folks contribute them, letting us dogfood our way to robust stable types.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};